/* ---------------- WORK ---------------- */
function WorkVisual({ w, ratio = "4 / 3", framed = false }) {
  const inner = w.img ? (
    <img src={w.img} alt={w.alt} loading="lazy"
      style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center", display: "block" }} />
  ) : (
    <span className="ph__tag" style={{ marginTop: "auto", maxWidth: "92%" }}>{w.alt}</span>
  );

  if (framed) {
    return (
      <div className="case-visual" style={{ position: "relative", aspectRatio: ratio }}>
        <div className="frame" style={{
          position: "absolute", inset: 0, overflow: "hidden",
          display: "flex", alignItems: "flex-end",
          background: w.img ? "var(--surface)" : (TONE_BG[w.tone] || "var(--surface)"),
        }}>
          {inner}
        </div>
        <CropMarks color="var(--accent)" />
      </div>
    );
  }

  if (w.img) {
    return (
      <div className="case-visual" style={{ aspectRatio: ratio, borderRadius: "var(--radius)",
        overflow: "hidden", border: "1px solid var(--line)", background: "var(--surface)" }}>
        {inner}
      </div>
    );
  }
  return (
    <div className="ph case-visual" style={{ aspectRatio: ratio, background: TONE_BG[w.tone] || "var(--surface)",
      borderColor: "var(--line)", alignItems: "flex-start" }}>
      <span className="ph__tag" style={{ marginTop: "auto", maxWidth: "92%" }}>{w.alt}</span>
    </div>
  );
}

function ServiceTags({ items }) {
  return (
    <div className="chips" style={{ marginTop: 4 }}>
      {items.map((s) => <span key={s} className="chip" style={{ pointerEvents: "none", color: "var(--ink-2)" }}>{s}</span>)}
    </div>
  );
}

/* Gallery tile with graceful placeholder until the real pouch image is added */
function GalleryTile({ src, alt, label }) {
  const [err, setErr] = useState(false);
  return (
    <div style={{ background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 8, overflow: "hidden", aspectRatio: "4 / 5" }}>
      {err
        ? <div className="ph" style={{ width: "100%", height: "100%", alignItems: "center", justifyContent: "center", textAlign: "center" }}>
            <span className="ph__tag">{label || "Add image"}</span>
          </div>
        : <img src={src} alt={alt} loading="lazy" onError={() => setErr(true)}
            style={{ width: "100%", height: "100%", objectFit: "contain", display: "block" }} />}
    </div>
  );
}

/* Full case row (Work page) */
function WorkRow({ w, index }) {
  const { navigate } = useRouter();
  const flip = index % 2 === 1;
  return (
    <Reveal as="article" style={{ borderTop: "1px solid var(--line)", paddingBlock: "clamp(44px,6vw,88px)" }}>
      <div className="grid12 work-row" style={{ rowGap: 32, alignItems: "center" }}>
        <div className="col-span-6" style={{ order: flip ? 2 : 1 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
            <span className="tag tag--accent">FIG. {w.n}</span>
            <Measure label={`${w.sector}`} style={{ flex: 1 }} />
          </div>
          {w.gallery
            ? <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 10 }}>
                {w.gallery.map((g, i) => <GalleryTile key={g.src} src={g.src} alt={g.alt} label={w.skus ? w.skus[i] : ""} />)}
              </div>
            : <WorkVisual w={w} ratio="5 / 4" framed />}
        </div>
        <div className="col-span-6 work-row__body" style={{ order: flip ? 1 : 2 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 14, marginBottom: 18 }}>
            <span style={{ fontFamily: "var(--mono)", fontSize: 13, color: "var(--accent-deep)" }}>{w.n} —</span>
            <span style={{ fontFamily: "var(--mono)", fontSize: 12.5, color: "var(--ink-3)", letterSpacing: "0.03em" }}>{w.sector} · {w.year}</span>
          </div>
          <h3 className="display" style={{ fontSize: "clamp(28px,3.4vw,46px)", fontWeight: 600, letterSpacing: "-0.025em", lineHeight: 1.0 }}>
            {w.client}
          </h3>
          <p style={{ margin: "10px 0 0", fontFamily: "var(--serif)", fontStyle: "italic", fontSize: 19, color: "var(--accent-deep)" }}>{w.project}</p>
          <p style={{ margin: "20px 0 0", fontSize: 17.5, lineHeight: 1.6, color: "var(--ink-2)", maxWidth: "50ch", textWrap: "pretty" }}>{w.desc}</p>
          <ServiceTags items={w.services} />

          {w.skus && (
            <div style={{ marginTop: 24 }}>
              <p className="label" style={{ color: "var(--ink-3)", marginBottom: 12 }}>{w.skusLabel}</p>
              <div className="chips">
                {w.skus.map((s) => (
                  <span key={s} className="chip" style={{ pointerEvents: "none", background: "transparent", color: "var(--ink-2)" }}>{s}</span>
                ))}
              </div>
            </div>
          )}

          <a href="/api/checkout?tier=brand-gap-audit" className="txtlink" style={{ marginTop: 26 }}>
            Start one like this <Arrow />
          </a>
        </div>
      </div>
    </Reveal>
  );
}

function WorkRows() {
  return (
    <div style={{ borderBottom: "1px solid var(--line)" }}>
      {WORK_DATA.map((w, i) => <WorkRow key={w.id} w={w} index={i} />)}
    </div>
  );
}

/* Compact teaser card (Home preview) */
function CaseStudyCard({ w, index }) {
  const { navigate } = useRouter();
  return (
    <Reveal as="article" className="case-card" delay={(index % 3) * 70}
      onClick={() => navigate("work")}
      style={{ cursor: "pointer", display: "flex", flexDirection: "column", gap: 18 }}>
      <WorkVisual w={w} />
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 12 }}>
          <span style={{ fontFamily: "var(--mono)", fontSize: 12, color: "var(--accent-deep)", letterSpacing: "0.04em" }}>{w.n} — {w.client}</span>
          <span style={{ fontFamily: "var(--mono)", fontSize: 11.5, color: "var(--ink-3)" }}>{w.year}</span>
        </div>
        <h3 style={{ margin: "12px 0 0", fontFamily: "var(--display)", fontWeight: 600,
          fontSize: "clamp(20px,2vw,25px)", letterSpacing: "-0.02em", lineHeight: 1.1, textWrap: "balance" }}>
          {w.project}
        </h3>
        <p style={{ margin: "8px 0 0", fontSize: 14.5, color: "var(--ink-3)" }}>{w.sector}</p>
        <span className="txtlink" style={{ marginTop: 16, borderColor: "var(--line-2)" }}>
          View case study <Arrow />
        </span>
      </div>
    </Reveal>
  );
}

function WorkPreview() {
  return (
    <section className="section">
      <div className="wrap">
        <SectionHead
          label="Selected work" title="Brands we've helped find their space."
          lede="Identity, packaging, and systems work for founders and growing teams."
          linkTo="work" linkLabel="View all work"
        />
        <div className="work-grid" style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "clamp(20px,2.4vw,32px)" }}>
          {WORK_DATA.slice(0, 3).map((w, i) => <CaseStudyCard key={w.id} w={w} index={i} />)}
        </div>
      </div>
    </section>
  );
}

Object.assign(window, {
  WHO, SERVICES_DATA, PROCESS_DATA, WORK_DATA, TONE_BG,
  SectionHead, Hero, ValueStatement, ServiceRow, ServicesPreview,
  ProcessStepCard, ProcessSteps, ProcessPreview,
  WorkVisual, ServiceTags, GalleryTile, WorkRow, WorkRows, CaseStudyCard, WorkPreview,
});
